// 原公平计划不是代理权源；三人的阶段必须各由原委任、签字或Task接受事实证明。
#include "political_governance_agency_intent_validation.hpp"
#include "resident/kernel/governance_integration.hpp"
#include <set>
namespace hanmo::resident {
Status validate_political_governance_agency_intent_director(const DirectorCatalog& catalog,const DirectorState& state,const PoliticalGovernanceAgencyBusinessContext* business,const GovernanceReadContext* governance){
 const auto* intents=catalog.governance_agency_intents.get();if(bool(business)!=bool(governance)||bool(intents)!=bool(business))return common_failure("GovernanceAgencyIntentVersionPairRequired");
 if(intents){const auto& x=business->rules;if(x.state.version!=2||x.intents!=intents)return common_failure("GovernanceAgencyIntentCandidateMismatch");auto valid=validate_political_governance_agency_intents(*intents,x.common_catalog,x.politics_catalog,x.organization_catalog,x.catalog);if(!valid.ok)return valid;}
 const auto& policies=catalog.dynamic_subjects?catalog.policies:catalog.subjects;
 for(const auto& row:policies.rows()){const auto& p=row.second;const bool selected=std::find(p.templates.begin(),p.templates.end(),DirectorTemplate::governance_agency)!=p.templates.end();if(selected!=p.governance_agency_intent_id.has_value())return common_failure("GovernanceAgencyIntentDirectorPolicyMismatch",row.first);if(!selected)continue;const auto* i=intents?intents->intents.find(*p.governance_agency_intent_id):nullptr;if(!i||(row.first!=i->principal_director_policy_id&&row.first!=i->delegate_director_policy_id&&row.first!=i->executor_director_policy_id))return common_failure("GovernanceAgencyIntentDirectorPolicyMismatch",row.first);}
 if(intents)for(const auto& row:intents->intents.rows()){const auto& i=row.second;const auto* p=business->rules.catalog.policies.find(i.agency_policy_id);const auto* j=p?business->rules.politics_catalog.jurisdictions.find(p->jurisdiction_id):nullptr;if(!j)return common_failure("GovernanceAgencyIntentSourceMismatch",i.id);const std::pair<StableId,StableId> roles[]={{i.principal_actor_id,i.principal_director_policy_id},{i.delegate_actor_id,i.delegate_director_policy_id},{i.executor_actor_id,i.executor_director_policy_id}};for(const auto& role:roles){const auto* selected=policies.find(role.second);if(!selected||selected->organization_id!=j->political_organization_id||selected->governance_agency_intent_id!=std::optional<StableId>{i.id}||std::find(selected->templates.begin(),selected->templates.end(),DirectorTemplate::governance_agency)==selected->templates.end()||(!catalog.dynamic_subjects&&role.first!=role.second))return common_failure("GovernanceAgencyIntentDirectorPolicyMismatch",role.second);}}
 // 原producer保留next_review=review_tick+原delay，归档复制该字段，不能用今日钟倒填后发来源。
 const auto plans=[&](const OrderedTable<FinitePlan>& table,bool archived)->Status{for(const auto& row:table.rows()){const auto& p=row.second;if(p.template_id!=political_governance_agency_intent_template)continue;const auto policy_id=catalog.dynamic_subjects?p.policy_id:p.subject.id;const auto* policy=policies.find(policy_id);const auto* i=policy&&policy->governance_agency_intent_id&&intents?intents->intents.find(*policy->governance_agency_intent_id):nullptr;if(!business||!governance||!i||p.subject.kind!=SubjectKind::actor||(p.subject.id!=i->principal_actor_id&&p.subject.id!=i->delegate_actor_id&&p.subject.id!=i->executor_actor_id)||!p.commitment_ids.empty()||p.livelihood||p.pending_life_action_id||p.last_life_fact_id||(p.phase!=PlanPhase::waiting&&p.phase!=PlanPhase::delivering&&p.phase!=PlanPhase::accepting&&p.phase!=PlanPhase::completed))return common_failure("GovernanceAgencyIntentDirectorPlanMismatch",row.first);
 const auto expected=p.subject.id==i->principal_actor_id?i->principal_director_policy_id:p.subject.id==i->delegate_actor_id?i->delegate_director_policy_id:i->executor_director_policy_id;if(policy_id!=expected||(p.subject.id==i->executor_actor_id&&!i->executor_accepts))return common_failure("GovernanceAgencyIntentDirectorPolicyMismatch",row.first);
 const Integer delay=std::max(catalog.retry_delay_ticks,catalog.review_interval_ticks);if(delay<1||p.next_review_tick<delay)return common_failure("GovernanceAgencyIntentScheduleRequired",row.first);const Integer observed=p.next_review_tick-delay;if(observed>business->rules.common.tick())return common_failure("GovernanceAgencyIntentScheduleRequired",row.first);if(!archived){const auto* schedule=state.schedules.find(p.subject.id);if(!schedule||schedule->last_decision_tick!=observed||schedule->next_tick!=p.next_review_tick)return common_failure("GovernanceAgencyIntentScheduleRequired",row.first);}
 PoliticalGovernanceAgencyIntentAccess read(*business,*governance,policy_id);if(p.phase==PlanPhase::completed){if(p.current_action_id)return common_failure("GovernanceAgencyIntentCompletedActionMismatch",row.first);auto valid=read.completed_before_review(*i,p.subject.id,p.goal_ref,observed);if(!valid.ok)return valid;continue;}if(p.goal_ref!=i->id)return common_failure("GovernanceAgencyIntentGoalMismatch",row.first);
 if(p.phase==PlanPhase::accepting){auto known=read.agency_intent_known(p.subject.id,*i);if(!known.ok)return {false,{},known.error};if(p.subject.id==i->principal_actor_id){if(p.current_action_id)return common_failure("GovernanceAgencyIntentUnexpectedAction",row.first);auto valid=read.completed_before_review(*i,p.subject.id,known.value.known_offer_fact_id,observed);if(!valid.ok)return valid;}else if(p.subject.id==i->delegate_actor_id){if(p.current_action_id)return common_failure("GovernanceAgencyIntentUnexpectedAction",row.first);const auto* a=business->rules.state.answers.find(known.value.own_answer_fact_id);if(!a||a->tick>observed)return common_failure("GovernanceAgencyIntentAcceptedSourceRequired",row.first);}else{auto valid=read.completed_before_review(*i,p.subject.id,known.value.own_task_acceptance_fact_id,observed);if(!valid.ok)return valid;const GovernanceTaskContract* accepted=nullptr;for(const auto& contract:governance->governance_tasks.governance_contracts.rows())if(contract.second.acceptance.fact_id==known.value.own_task_acceptance_fact_id)accepted=&contract.second;if(!archived&&(!p.current_action_id||!accepted||accepted->action_id!=*p.current_action_id))return common_failure("GovernanceAgencyIntentAcceptedActionRequired",row.first);}}
 }return common_success();};auto valid=plans(state.plans,false);return valid.ok?plans(state.archived_plans,true):valid;
}
}
